import assert from 'node:assert/strict';import {execFile} from 'node:child_process';import {promisify} from 'node:util';import {mkdtemp,mkdir,readFile,rm,symlink,writeFile} from 'node:fs/promises';import {createServer} from 'node:http';import {tmpdir} from 'node:os';import {join} from 'node:path';
import {loadConfig} from "file:///home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/config.js";
import {parseCustomProviders} from "file:///home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/custom-providers.js";
import {PiBackend} from "file:///home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/mcp/backends/pi.js";
import {LegacyMikroBackend} from "file:///home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/mcp/backends/legacy.js";
import {parseAgentSpec} from "file:///home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/sdk/agent-spec.js";
import {runTurn} from "file:///home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/mcp/server.js";
import {rlmLoop} from "file:///home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/rlm.js";
async function fixture(turns, onRequest) {
    const root = await mkdtemp(join(tmpdir(), "mikro-pi-"));
    const bodies = [];
    const server = createServer(async (req, res) => {
        let text = "";
        for await (const chunk of req)
            text += chunk;
        bodies.push(JSON.parse(text));
        const index = bodies.length - 1;
        const turn = turns[index];
        onRequest?.(index);
        if (!turn) {
            res.writeHead(500);
            res.end("unexpected request");
            return;
        }
        if (turn.httpError) {
            res.writeHead(400, { "Content-Type": "application/json" });
            res.end(JSON.stringify({ error: { message: "fixture provider refused" } }));
            return;
        }
        res.writeHead(200, { "Content-Type": "text/event-stream" });
        if (turn.hang) {
            res.write('data: {"choices":[{"index":0,"delta":{"role":"assistant"},"finish_reason":null}]}\n\n');
            return;
        }
        const delta = turn.tools ? { role: "assistant", tool_calls: turn.tools.map((tool, index) => ({ index, id: `tool-${bodies.length}-${index}`, type: "function", function: { name: tool.name, arguments: JSON.stringify(tool.args) } })) } : { role: "assistant", content: turn.text ?? "not a final" };
        res.end(`data: ${JSON.stringify({ id: `fixture-${bodies.length}`, choices: [{ index: 0, delta, finish_reason: turn.finish ?? (turn.tools ? "tool_calls" : "stop") }], usage: { prompt_tokens: 11, completion_tokens: 7, total_tokens: 18 } })}\n\ndata: [DONE]\n\n`);
    });
    await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
    const address = server.address();
    if (!address || typeof address === "string")
        throw new Error("fixture needs TCP address");
    const baseUrl = `http://127.0.0.1:${address.port}/v1`;
    const keyEnv = "MIKRO_PI_FIXTURE_KEY";
    const previousKey = process.env[keyEnv];
    process.env[keyEnv] = "fixture-only-key";
    const base = await loadConfig(root);
    const config = {
        ...base, system: "Explicit test role", criteria: null, tools: [], validate: null,
        output: { schema: null }, budget: { maxCost: null, maxTokens: null, maxDepth: null },
        gemini: { ...base.gemini, thinkingLevel: null },
        model: { provider: "pi-fixture", model: "control", providers: parseCustomProviders({ "pi-fixture": { "base-url": baseUrl, "api-key-env": keyEnv, models: { control: { cost: { input: 1, output: 2 } } } } }, "test fixture") },
    };
    return {
        root, config, bodies, baseUrl, keyEnv,
        request(overrides = {}) { return { cwd: root, query: "Answer from scoped files", context: null, config, maxRetries: 0, ...overrides }; },
        agent(yaml = "engine: pi\nshape: loop\n") { return { name: "fixture", toolName: "mikro_fixture", dir: root, summary: "fixture", spec: parseAgentSpec(yaml, root) }; },
        async close() {
            if (previousKey === undefined)
                delete process.env[keyEnv];
            else
                process.env[keyEnv] = previousKey;
            server.closeAllConnections();
            await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
            await rm(root, { recursive: true, force: true });
        },
    };
}
const observations=[];
for(const candidate of ['GOOD','OTHER']){
 const local=await fixture([{text:"```repl\nprint('first observation')\n```"},{text:`FINAL({"answer":"${candidate}"})`}]);
 try{
  const config={...local.config,system:null,output:{schema:{type:'object',properties:{answer:{type:'string',enum:['GOOD','OTHER']}},required:['answer']}},validate:{schema:{type:'object',properties:{answer:{type:'string',enum:['GOOD']}},required:['answer']},rawBlock:'{"type":"object","properties":{"answer":{"type":"string","enum":["GOOD"]}},"required":["answer"]}'}};
  const result=await rlmLoop('Finalize inside exactly two allowed model turns',null,config,{maxIterations:2,maxRetries:0,timeout:10000,output:'json'});
  assert.equal(local.bodies.length,2);assert.equal(result.iterations,2);assert.equal(result.usage.llmCalls,2);assert.equal(result.answer,JSON.stringify({answer:candidate}));assert.equal(result.validation_failed===true,candidate==='OTHER');
  observations.push({candidate,actualSdkProviderRequests:local.bodies.length,iterations:result.iterations,llmCalls:result.usage.llmCalls,answer:result.answer,validationFailed:result.validation_failed===true,extraFinalCall:false,lastRequest:local.bodies[1].messages.at(-1).content,usage:result.usage});
 }finally{await local.close();}
}
console.log(JSON.stringify({entry:'Actual compiled rlmLoop, actual Python and SDK/local HTTP fixture',maxIterations:2,outputSchemaAndValidateBothApplied:true,externalInferenceCalls:0,observations}));
